c_4 &= \frac{{\mathrm e}^{ \alpha H} \alpha (-H^{2} \alpha^{2}+4 \,{\mathrm e}^{ \alpha H} H \alpha -2 \,{\mathrm e}^{2 \alpha H})}{2} \\
c_5 &= \frac{{\mathrm e}^{ \alpha H} (-6 \,{\mathrm e}^{3 \alpha H}+(18 \,{\mathrm e}^{2 \alpha H}+ \alpha H ( \alpha H -12 \,{\mathrm e}^{ \alpha H})) \alpha H) \alpha}{6} 
