nodes.statement:
\textbf{Step I:}
In this step we prove that if $\pi\in\mathcal A$ satisfies 
$\mathbb E_{\mathbb P}\left[\exp\left(-V^{ \pi}_n\right)\right]<\infty$ then 
for any $\mathbb Q\in\mathcal Q$ 
\begin{equation} \mathbb E_{\mathbb Q}[V^{\pi}_n]=0.
\end{equation}

Thus, using similar arguments as in the proof of Lemma 2.1 in \cite{BD:2021}
we obtain (in view of (\ref{2.0})) that 
 $\mathbb E_{\mathbb Q}\left[\sum_{i=1}^n \gamma_i X_i\right]=0$.

\textbf{Step I:} 
 Set $v=(v_0,...,v_{n-1})$ by 
 \begin{equation} v_0=\frac{a D+1}{a(D+1)+1}, \ \ v_1=...=v_{D}=\frac{-a}{a(D+1)+1}, \ \ v_{D+1}=...=v_{n-1}=0.
 \end{equation}
 In this step we prove that 
 \begin{equation} \sum_{j=0}^{n-1} v_j b_{|i-j|}=\delta_{i0}, \ \ i=0,1...,n-1.
 \end{equation} 
 This is shown by straightforward derivation for the different cases of $i$.

\noindent For $1 \leq i < {D}$:
\begin{align*}
\sum_{j=0}^{n-1} v_j b_{|i-j|} &=
v_0 b_{i}+v_i b_0 +\sum_{j=1}^{i-1} v_j b_{i-j}+\sum_{j=i+1}^{{D}} v_j b_{j-i} \\
&= \frac{a (a D+1)- a(a+1)-a^2 (D-1)}{a({D}+1)+1} = 0.
\end{align*}

\noindent For $i\geq {D}$: 
\begin{align*}
\sum_{j=0}^{n-1} v_j b_{|i-j|} &= \sum_{j=0}^{D} v_j b_{i-j}\\
&= \frac{a D+1}{a({D}+1)+1} \left( b_{i}-\frac{a}{aD+1} \sum_{j=1}^{{D}} b_{i-j}\right)=0
\end{align*}
where the last equality follows from the recursive relation in (\ref{1.4}). This completes the first step.

\textbf{Step II:}
 In this step we complete the proof. 
 From Theorem 1
 in \cite{rodman1992inversion} and \eqref{2.15}
 \begin{equation} [A^{-1}]_{ij}=\frac{1}{v_0}\left(\sum_{k=1}^{i\wedge j} v_{i-k}v_{j-k}-\sum_{k=1}^{i\wedge j-1 }v_{n-i+k}v_{n-j+k}\right).
 \end{equation}

Thus, in view of Lemma \ref{lem2.1} in order to complete the proof of Theorem \ref{thm1.1}
we need to show that 
$\hat{\mathbb Q}\in\mathcal Q$.

From 
(\ref{eq:b_sol_recursive}) and the product rule (for differentiation) we obtain that for any $t\in (kH,(k+1)H)$ 
\begin{align*}
\frac{d}{dt}\kappa_t-\alpha \kappa_t &=-\frac{\alpha^2}{1-\alpha H}
+\exp\big(\alpha\left(t- k H\right)\big) \sum_{j=1}^{k-1} j c_{k-j} \frac{(-\alpha)^j}{j!} (t-kH)^{j-1}\\
&=-\frac{\alpha^2}{1-\alpha H}-\alpha
\exp\big(\alpha\left(t- k H\right)\big) \sum_{j=0}^{k-2} c_{k-1-j} \frac{(-\alpha)^j}{j!} (t-kH)^{j}\\
&=-\alpha\kappa_{t-H}.
\end{align*}

From $V^{\pi}_1=V^{\tilde\pi}_1$ we get
\begin{equation} h\left(W_{1-\frac{1}{n}}+B_{\frac{1}{n}}\right)=\int_{0}^{1-\frac{1}{n}}\beta_t dW_t+\int_{0}^{\frac{1}{n}}\beta_{s+1-\frac{1}{n}}dB_s.
\end{equation}

Choose $n\in\mathbb N$. We apply Theorem \ref{thm1.1} to the sequence 
 $S_k:=P_{k/n}$, $k=0,1...,n$. 
Thus, let $D=D_n$, $\mu=\frac{\theta}{n}$, $\sigma=\frac{\varsigma}{\sqrt n}$, $\hat\sigma=\frac{\hat\varsigma}{\sqrt n}$.
From (\ref{1.6}) and (\ref{4.4}) we obtain
\begin{align*}
&\lim_{n\rightarrow\infty} U_n(H,\mu,\varsigma,\hat\varsigma)\\
&=-\exp\left(\frac{1}{2}\left(-\frac{\theta^2}{\varsigma^2}+\lim_{n\rightarrow\infty}\left(na_n\frac{\hat\varsigma^2}{\varsigma^2}-\frac{a_n(n-D_n)}{1+a_n D_n}\right)\right)\right)\frac{1}{\sqrt{1+\lim_{n\rightarrow\infty} a_n D_n}}\\
&=-{\exp\left(\frac{1}{2}\left(-\frac{\theta^2}{\varsigma^2}+
\alpha\left(\frac{\hat\varsigma^2}
{\varsigma^2(1-\alpha H)}+H-1\right)\right)\right)}\sqrt{1-\alpha H}
\end{align*}
and (\ref{4.0}) follows.

Thus, in order to prove (\ref{6.2}) for $k-1$ it remains to establish that 
\begin{equation} \mathbb E_{\mathbb P}\left[\int_{\frac{k-1}{n}}^{\frac{k}{n}} \gamma_t dW_t\left|\right. \mathcal F_{\frac{k-1}{n}}\right]=0.
\end{equation}

\textbf{Step III:}
First, in view of \textbf{Step II}, by applying the same arguments as after 
(\ref{2.6}) we obtain that for any $\epsilon>0$
\begin{equation} \log\left(\mathbb E_{\mathbb P}\left[\exp\left(-V^{\pi}_1\right)\right] \right)\geq -\mathbb E_{\mathbb Q(l)}\left[\log\left(\frac{d\mathbb Q(l)}{d\mathbb P}\right)\right] \ \ \forall (\pi,l)\in\mathfrak A\times\Gamma_{\epsilon}.
\end{equation}
